int main(){try{using T=ks::NativeArpEmitService;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;for(unsigned octave:{0u,1u,11u,255u})for(unsigned seed=0;seed<32;++seed)for(unsigned policy:{0u,32u,64u,96u}){std::fill(m.begin()+0x15000,m.begin()+0x30000,uint8_t(0));const unsigned part=seed%5,rec=0x160d2+334*part;const auto word=[&](unsigned at,uint16_t v){m[at]=uint8_t(v>>8);m[at+1]=uint8_t(v);};m[0x174ae +20*part]=0;m[0x174af+20*part]=1;m[0x174b0+20*part]=0x80;m[0x174b1+20*part]=0;m[0x174ae +20*part+14]=64;m[0x18000]=16;m[0x18000+173]=8;m[0x174a6]=4;m[0x17526]=uint8_t(part);m[rec+329]=uint8_t(seed&1);m[rec+319]=uint8_t(seed);m[rec+326]=uint8_t(octave);m[rec+311]=1;m[rec+312]=uint8_t(1+seed%3);m[rec+313]=2;m[rec+327]=uint8_t(policy);word(rec+304,100);word(rec+14,50);word(rec+12,75);for(unsigned j=0;j<32;++j)m[rec+16+j]=60;m[0x160d0]=uint8_t(seed&1);m[0xffff8a]=0xf0;word(0xffed6c,0);word(0xffed6e,128);unsigned local=0;int previous=-1;tracking=true;{T g({uint8_t(part),0x643c});while(!g.complete()){struct Unknown{};check(!g.task<Unknown>(),"Unknown Emit task");const auto cost=g.nextClocks(previous);check(cost,"Emit stalled");std::array<unsigned char,sizeof(T)>before{};std::memcpy(before.data(),&g,sizeof(T));unsigned callbacks=0;check(!g.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},previous)&&!callbacks&&!std::memcmp(before.data(),&g,sizeof(T)),"Emit budget mutated graph");++rejects;check(g.advanceBefore(cost,[&](uint32_t a,unsigned dt){check(a<m.size()&&dt&&dt<=cost,"Emit read span/time");++reads;return a==0x400004||a==0x600004?uint8_t(255):m[a];},[&](uint32_t a,uint8_t v,unsigned dt){check(a<m.size()&&dt&&dt<=cost&&!(a>=0xfff000&&a<0xfffc00),"Emit write span/time");m[a]=v;previous=a<0x400000?int(a):-1;++writes;},previous)==cost,"Emit phase admission");if(g.effect().write)previous=-1;check(++local<20000,"Emit noncompletion");++phases;}const uint8_t played=uint8_t(60+12*octave);check(m[rec+322]==60,"Emit original note publication");if(!(played&128))check(m[rec+311]==1&&m[rec+312]==1&&m[rec+320]==1&&m[rec+16]==played,"Emit append queue oracle");struct A{std::array<uint32_t,7>values{};uint8_t flags=0xa5;}a;a.values[5]=0x1234643c;a.values[6]=0x23456789;projectNativeArpEmit(a,g);check(g.expressionSourceAfter(0x1234643c)==a.values[5]&&g.notificationAfter(0x23456789)==a.values[6],"Emit semantic context result differs");components|=g.components();}tracking=false;++graphs;}check(!allocations,"Emit heap");std::cout<<"PASS Pure NativeArpEmit graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
